import { test, expect } from '@playwright/test';
import * as fs from 'fs';
import * as path from 'path';

test.describe('File Download Export Functionality', () => {
  let downloadPath: string;

  test.beforeEach(async ({ page, context }) => {
    downloadPath = path.join(__dirname, 'downloads');

    if (!fs.existsSync(downloadPath)) {
      fs.mkdirSync(downloadPath, { recursive: true });
    }

    await context.tracing.start({ screenshots: true, snapshots: true });
    await page.goto('https://example.com');
  });

  test('should download file when export button is clicked', async ({ page, context }) => {
    const downloadPromise = page.waitForEvent('download');

    const exportButton = page.getByRole('button', { name: /export/i });
    await expect(exportButton).toBeVisible();
    await exportButton.click();

    const download = await downloadPromise;
    expect(download.suggestedFilename()).toBeTruthy();

    const filePath = path.join(downloadPath, download.suggestedFilename());
    await download.saveAs(filePath);

    expect(fs.existsSync(filePath)).toBeTruthy();
    const fileSize = fs.statSync(filePath).size;
    expect(fileSize).toBeGreaterThan(0);
  });

  test('should download CSV file with correct format', async ({ page, context }) => {
    const downloadPromise = page.waitForEvent('download');

    const csvExportButton = page.getByRole('button', { name: /export as csv/i });
    await expect(csvExportButton).toBeVisible();
    await csvExportButton.click();

    const download = await downloadPromise;
    expect(download.suggestedFilename()).toMatch(/\.csv$/i);

    const filePath = path.join(downloadPath, download.suggestedFilename());
    await download.saveAs(filePath);

    const fileContent = fs.readFileSync(filePath, 'utf-8');
    expect(fileContent).toContain(',');
    expect(fileContent.length).toBeGreaterThan(0);
  });

  test('should handle multiple sequential downloads', async ({ page, context }) => {
    const exportButton = page.getByRole('button', { name: /export/i });

    for (let i = 0; i < 2; i++) {
      const downloadPromise = page.waitForEvent('download');
      await exportButton.click();

      const download = await downloadPromise;
      const filename = download.suggestedFilename();
      const filePath = path.join(downloadPath, `${i}_${filename}`);

      await download.saveAs(filePath);
      expect(fs.existsSync(filePath)).toBeTruthy();
    }
  });

  test('should verify download button is enabled before export', async ({ page }) => {
    const exportButton = page.getByRole('button', { name: /export/i });

    await expect(exportButton).toBeEnabled();
    await expect(exportButton).toBeVisible();

    const isDisabled = await exportButton.isDisabled();
    expect(isDisabled).toBeFalsy();
  });

  test('should handle download with custom filename', async ({ page, context }) => {
    const downloadPromise = page.waitForEvent('download');

    const customExportButton = page.getByRole('button', { name: /export with custom name/i });

    if (await customExportButton.isVisible()) {
      await customExportButton.click();

      const download = await downloadPromise;
      const filename = download.suggestedFilename();

      expect(filename).toBeTruthy();
      expect(filename.length).toBeGreaterThan(0);

      const filePath = path.join(downloadPath, filename);
      await download.saveAs(filePath);
      expect(fs.existsSync(filePath)).toBeTruthy();
    }
  });

  test.afterEach(async ({ context }) => {
    await context.tracing.stop({ path: path.join(__dirname, 'trace.zip') });

    if (fs.existsSync(downloadPath)) {
      const files = fs.readdirSync(downloadPath);
      files.forEach(file => {
        const filePath = path.join(downloadPath, file);
        if (fs.statSync(filePath).isFile()) {
          fs.unlinkSync(filePath);
        }
      });
    }
  });
});
